        return {
            "check_name": check_name,
            "passed": False,
            "message": f"Error reading file: {filepath} - {str(e)}"
        }
    return {
        "check_name": check_name,
        "passed": True,
        "message": f"File has data: {filepath}"
    }


def check_csv_headers(filepath: str, check_name: str, expected_headers: list) -> dict:
    """Check if a CSV file has the expected headers."""
    path = Path(filepath)
    if not path.exists():
        return {
            "check_name": check_name,
            "passed": False,
            "message": f"File not found: {filepath}"
        }
    try:
        with open(path, 'r', encoding='utf-8') as f:
            header_line = f.readline().strip()
            if not header_line:
                return {
                    "check_name": check_name,
                    "passed": False,
                    "message": f"File has no header: {filepath}"
                }
            actual_headers = header_line.split(',')
            if actual_headers != expected_headers:
                return {
                    "check_name": check_name,
                    "passed": False,
                    "message": f"Headers mismatch in {filepath}. Expected: {expected_headers}, Got: {actual_headers}"
                }
    except Exception as e:
        return {
            "check_name": check_name,
            "passed": False,
            "message": f"Error reading file: {filepath} - {str(e)}"
        }
    return {
        "check_name": check_name,
        "passed": True,
        "message": f"Headers valid: {filepath}"
