def check_numeric_columns(filepath: str, check_name: str, numeric_columns: list) -> dict:
    """Check if specified columns contain numeric values."""
    path = Path(filepath)
    if not path.exists():
        return {
            "check_name": check_name,
            "passed": False,
            "message": f"File not found: {filepath}"
        }
