            data_row = lines[1].strip().split(',')
            for col in numeric_columns:
                col_idx = header.index(col)
                if not data_row[col_idx].strip():
                    return {
                        "check_name": check_name,
                        "passed": False,
                        "message": f"Column '{col}' is empty in first data row of {filepath}"
