    results.append(check_csv_headers(
        "outputs/t05_clean_stops.csv",
        "t05_headers_valid",
        ["stop_id", "stop_name", "stop_lat", "stop_lon"]
    ))

    # Check 6: t05_clean_stops.csv has numeric coordinates
    results.append(check_numeric_columns(
        "outputs/t05_clean_stops.csv",
        "t05_numeric_columns_valid",
        ["stop_lat", "stop_lon"]
    ))

    # Check 7: t05_clean_stops.csv has minimum rows
    results.append(check_row_count("outputs/t05_clean_stops.csv", "t05_minimum_rows", 10))

    # Check 8: t08_pois_clean.csv exists
    results.append(check_file_exists("outputs/t08_pois_clean.csv", "t08_file_exists"))

