            lines = f.readlines()
            if len(lines) < 2:
                return {
                    "check_name": check_name,
                    "passed": False,
                    "message": f"File has no data rows: {filepath}"
                }
            header = lines[0].strip().split(',')
            # Check if required columns exist
            for col in numeric_columns:
                if col not in header:
                    return {
                        "check_name": check_name,
                        "passed": False,
                        "message": f"Column '{col}' not found in {filepath}"
                    }
            # Check first data row for numeric values
            data_row = lines[1].strip().split(',')
            for col in numeric_columns:
                col_idx = header.index(col)
                if not data_row[col_idx].strip():
                    return {
                        "check_name": check_name,
                        "passed": False,
                        "message": f"Column '{col}' is empty in first data row of {filepath}"
                    }
    except Exception as e:
        return {
            "check_name": check_name,
            "passed": False,
            "message": f"Error reading file: {filepath} - {str(e)}"
        }
    return {
        "check_name": check_name,
        "passed": True,
        "message": f"Numeric columns valid: {filepath}"
    }


def check_row_count(filepath: str, check_name: str, min_rows: int) -> dict:
    """Check if a file has at least a minimum number of rows."""
    path = Path(filepath)
    if not path.exists():
        return {
            "check_name": check_name,
            "passed": False,
            "message": f"File not found: {filepath}"
        }
    try:
        with open(path, 'r', encoding='utf-8') as f:
            lines = f.readlines()
            data_rows = len(lines) - 1  # Subtract header
            if data_rows < min_rows:
                return {
                    "check_name": check_name,
                    "passed": False,
                    "message": f"File has only {data_rows} data rows, expected at least {min_rows}: {filepath}"
                }
    except Exception as e:
        return {
            "check_name": check_name,
            "passed": False,
            "message": f"Error reading file: {filepath} - {str(e)}"
        }
    return {
        "check_name": check_name,
        "passed": True,
        "message": f"Row count valid ({data_rows} data rows): {filepath}"
    }


